// A classic manual Thunk function
export const fetchUserData = (userId) => {
  // Notice we return a FUNCTION, not an object!
  return async (dispatch, getState) => {

    // 1. Dispatch a 'loading' action
    dispatch({ type: 'user/fetchStarted' });

    try {
      // 2. Do the async work
      const response = await fetch(`/api/users/${userId}`);
      const data = await response.json();

      // 3. Dispatch the 'success' action with the data
      dispatch({ type: 'user/fetchSuccess', payload: data });

    } catch (error) {
      // 4. Dispatch the 'error' action
      dispatch({ type: 'user/fetchFailed', error: error.message });
    }
  };
};
